"use strict";
/* Generated by scripts/build_site.py. Caches only same-origin static files; cross-origin requests (e.g. the HIBP lookup) are never intercepted or cached. */
const CACHE="__CACHE__";
const FILES=__FILES__;
self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES.map(f=>new URL(f,self.registration.scope).href))).then(()=>self.skipWaiting()))});
self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(k=>Promise.all(k.filter(n=>n!==CACHE).map(n=>caches.delete(n)))).then(()=>self.clients.claim()))});
self.addEventListener("fetch",e=>{const r=e.request,u=new URL(r.url);
if(r.method!=="GET"||u.origin!==self.location.origin||u.search)return;
e.respondWith(caches.open(CACHE).then(c=>c.match(r).then(hit=>{const net=fetch(r).then(res=>{if(res.ok&&res.type==="basic")c.put(r,res.clone());return res}).catch(()=>hit||(r.mode==="navigate"?c.match(new URL("404.html",self.registration.scope).href):Response.error()));return hit||net})))});
